-- Creates the PRD 7.4 roles plus the outbox dispatcher (P7.1, D-076). Run once per cluster
-- by an administrative connection.
-- No passwords here: local setup sets throwaway ones in scripts/db.mjs, and hosted
-- passwords are generated by the owner at the provider (docs/ENVIRONMENTS.md).
DO $$
DECLARE r text;
BEGIN
  FOREACH r IN ARRAY ARRAY['opsbridge_migrator','opsbridge_app','opsbridge_cleanup','opsbridge_dispatcher'] LOOP
    IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = r) THEN
      EXECUTE format('CREATE ROLE %I NOLOGIN', r);
    END IF;
    EXECUTE format('ALTER ROLE %I NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS', r);
  END LOOP;
  -- A flood must fail fast instead of holding connections.
  ALTER ROLE opsbridge_app SET statement_timeout = '5s';
  ALTER ROLE opsbridge_cleanup SET statement_timeout = '30s';
  ALTER ROLE opsbridge_dispatcher SET statement_timeout = '5s';
  EXECUTE format('GRANT CREATE, CONNECT ON DATABASE %I TO opsbridge_migrator', current_database());
  EXECUTE format('GRANT CONNECT ON DATABASE %I TO opsbridge_app, opsbridge_cleanup, opsbridge_dispatcher', current_database());
END $$;
